WM = '<span class="wm" aria-hidden="true"><small>KITCHEN CABINETRY</small></span>'
CSS = '<style id="fma-wm-fix">.logo .wm small{white-space:nowrap}@media (max-width:520px){.hdr .logo .wm{display:none}.hdr .logo{min-width:0;flex-shrink:1}.hdr .logo svg{height:28px}}@media (max-width:360px){.hdr .logo svg{height:24px}}@media (max-width:520px){.ftr .logo{flex-direction:column;align-items:flex-start;gap:.6rem}}</style>'
def run():
    for f in glob.glob(ROOT + '*.html'):
        s = open(f).read(); o = s
        s = re.sub(r'(<a [^>]*class="logo"[^>]*>)\s*<svg.*?</svg>\s*<span class="wm"[^>]*>.*?</span>', lambda m: m.group(1) + SVG + WM, s, flags=re.S)
        s = s.replace('favicon-maison.svg', 'favicon-fma.svg').replace('og-maison.png', 'og-fma.png')
        if 'fma-wm-fix' not in s: s = s.replace('</head>', CSS + '</head>', 1)
        assert 'favicon-maison' not in s and s.count('class="fma-wm"') >= 2, f
        if s != o: open(f, 'w').write(s)
if __name__ == '__main__': run(); print('door-M logo applied')
